import json

def read_config(path: str) -> dict:
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        raise SystemExit(f'Config file not found: {path}')
    except json.JSONDecodeError as e:
        raise SystemExit(f'Invalid JSON in {path}: {e}')
